{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n <= 1:
        return {"mst_edges": [], "total_weight": 0.0}
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))
    edges.sort()
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == n - 1:
                break
    if len(mst) != n - 1:
        raise ValueError("Disconnected graph; cannot compute MST.")
    return {"mst_edges": mst, "total_weight": total}"
}
